from pathlib import Path
import json
import pandas as pd, matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]; tab=ROOT/'results/tables/audio'; fig=ROOT/'results/figures/audio'; fig.mkdir(parents=True,exist_ok=True)
def main():
 images=pd.read_csv(ROOT/'results/tables/dataset_inventory.csv',parse_dates=['timestamp']); images=images[images.is_readable].sort_values('timestamp'); files=pd.read_csv(tab/'audio_file_features_july13_18.csv',parse_dates=['start_timestamp','end_timestamp']); peaks=pd.read_csv(tab/'audio_candidate_peaks_july13_18.csv',parse_dates=['absolute_peak_timestamp']); high=peaks.prominence>=peaks.prominence.quantile(.9); rows=[]
 for im in images.itertuples(index=False):
  row={'image_filename':im.filename,'image_timestamp':im.timestamp}; prev=peaks[peaks.absolute_peak_timestamp<=im.timestamp]; nxt=peaks[peaks.absolute_peak_timestamp>=im.timestamp]; row.update({'nearest_candidate_peak_before':prev.absolute_peak_timestamp.iloc[-1] if len(prev) else pd.NaT,'seconds_since_previous_peak':(im.timestamp-prev.absolute_peak_timestamp.iloc[-1]).total_seconds() if len(prev) else None,'nearest_candidate_peak_after':nxt.absolute_peak_timestamp.iloc[0] if len(nxt) else pd.NaT,'seconds_until_next_peak':(nxt.absolute_peak_timestamp.iloc[0]-im.timestamp).total_seconds() if len(nxt) else None})
  for direction,sign in [('previous',-1),('following',1)]:
   for minutes in (5,15,30,60):
    a,b=(im.timestamp-pd.Timedelta(minutes=minutes),im.timestamp) if sign<0 else (im.timestamp,im.timestamp+pd.Timedelta(minutes=minutes)); covered=files[(files.start_timestamp>=a)&(files.start_timestamp<=b)]; ev=peaks[(peaks.absolute_peak_timestamp>=a)&(peaks.absolute_peak_timestamp<=b)]; sec=covered.duration_seconds.sum(); key=f'{direction}_{minutes}min'; row[f'recorded_audio_seconds_{key}']=sec; row[f'candidate_peak_count_{key}']=len(ev) if sec else None; row[f'high_prominence_peak_count_{key}']=int((ev.prominence>=peaks.prominence.quantile(.9)).sum()) if sec else None; row[f'candidate_peaks_per_recorded_minute_{key}']=len(ev)/(sec/60) if sec else None; row[f'insufficient_coverage_{key}']=sec<max(5,minutes*60*.1)
  rows.append(row)
 out=pd.DataFrame(rows);out.to_csv(tab/'image_audio_alignment.csv',index=False); out.to_csv(tab/'image_audio_exploratory_features.csv',index=False)
 hourly=pd.read_csv(tab/'audio_hourly_summary_july13_18.csv',parse_dates=['hour']); fig_,axs=plt.subplots(3,1,figsize=(13,9),sharex=True,constrained_layout=True); axs[0].plot(hourly.hour,hourly.candidate_peaks_per_recorded_minute);axs[0].set_ylabel('Candidate peaks / recorded min');axs[1].plot(hourly.hour,hourly.high_prominence_peaks_per_recorded_minute);axs[1].set_ylabel('High-prominence / recorded min');axs[2].plot(hourly.hour,hourly.mean_rms);axs[2].set_ylabel('Mean RMS');fig_.suptitle('EXPLORATORY — coverage-normalized audio activity');fig_.savefig(fig/'daily_audio_activity_july13_18.png',dpi=140)
 fig2,ax=plt.subplots(figsize=(13,5));ax.plot(out.image_timestamp,out.candidate_peaks_per_recorded_minute_previous_60min,marker='o');ax.set_title('EXPLORATORY — audio activity before pilot image times');ax.set_ylabel('Candidate peaks / recorded min, previous 60 min');fig2.savefig(fig/'initial_image_audio_alignment.png',dpi=140,bbox_inches='tight')
 threshold=hourly.high_prominence_peaks_per_recorded_minute.quantile(.9); candidates=hourly[hourly.high_prominence_peaks_per_recorded_minute>=threshold].copy(); candidates['start_timestamp']=candidates.hour; candidates['end_timestamp']=candidates.hour+pd.Timedelta(hours=1); candidates['reason_selected']='Top-decile hourly high-prominence candidate-peak rate; exploratory follow-up only.'; candidates['audio_metric_involved']='high_prominence_peaks_per_recorded_minute'; candidates['image_metric_involved']='none; pilot image cadence is too sparse for second-level interpretation'; candidates['audio_coverage_seconds']=candidates.recorded_audio_seconds; candidates[['start_timestamp','end_timestamp','reason_selected','audio_metric_involved','image_metric_involved','audio_coverage_seconds']].to_csv(tab/'candidate_multimodal_windows.csv',index=False)
 status=json.loads((tab/'audio_phase1_status.json').read_text());status.update({'image_audio_alignment_complete':True,'candidate_multimodal_windows_complete':True,'ready_for_audio_phase2':True,'warnings':status.get('warnings',[])+['Pilot images are approximately hourly; this alignment cannot establish second-level biological timing.']});(tab/'audio_phase1_status.json').write_text(json.dumps(status,indent=2,default=str))
if __name__=='__main__':main()
